#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<long long> A(N);
    vector<int> order(N);
    for (int i = 0; i < N; ++i) {
        cin >> A[i];
        order[i] = i;
    }

    sort(order.begin(), order.end(), [&](int x, int y) {
        return A[x] < A[y];
    });

    vector<bool> active(N, false);
    int runs = 0;
    int maxRuns = 0;

    for (int i = 0; i < N;) {
        int j = i;
        while (j < N && A[order[j]] == A[order[i]]) {
            int pos = order[j];
            active[pos] = true;

            bool left = pos > 0 && active[pos - 1];
            bool right = pos + 1 < N && active[pos + 1];

            if (!left && !right) ++runs;
            else if (left && right) --runs;

            ++j;
        }

        maxRuns = max(maxRuns, runs);
        i = j;
    }

    cout << maxRuns + 1 << '\n';
    return 0;
}
